BEGIN READ ONLY; SELECT current_setting('transaction_read_only') AS transaction_read_only,current_database() AS database,current_user AS current_user,session_user AS session_user,version() AS postgresql_version,clock_timestamp() AS inspected_at,current_setting('cluster_name',true) AS cluster_name; ROLLBACK;

BEGIN READ ONLY; SELECT jsonb_build_object('inspected_at',clock_timestamp(),'transaction_read_only',current_setting('transaction_read_only'),'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'schema',n.nspname,'name',p.proname,'hash',md5(replace(p.prosrc,chr(13),'')),'source',p.prosrc,'definition',pg_get_functiondef(p.oid),'owner',p.proowner::regrole::text,'definer',p.prosecdef,'acl',p.proacl::text,'config',p.proconfig,'language',l.lanname,'effective_execute',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END,'grantor',a.grantor::regrole::text,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) ORDER BY n.nspname,p.proname,p.oid), '[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE p.prokind='f' AND n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema' AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.refclassid='pg_extension'::regclass AND d.deptype='e'))) AS catalog; ROLLBACK;

BEGIN READ ONLY;
SELECT jsonb_build_object(
 'inspected_at',clock_timestamp(),'transaction_read_only',current_setting('transaction_read_only'),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('table',i.indrelid::regclass::text,'name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),'primary',i.indisprimary,'unique',i.indisunique,'valid',i.indisvalid,'ready',i.indisready,'columns',(SELECT jsonb_agg(a.attname ORDER BY k.ordinality) FROM unnest(i.indkey) WITH ORDINALITY k(attnum,ordinality) LEFT JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=k.attnum)) ORDER BY i.indrelid::regclass::text,ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid IN ('public.listings'::regclass,'public.donation_claims'::regclass,'public.claim_requests'::regclass,'public.claim_leases'::regclass,'public.pickup_tasks'::regclass)),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid),'validated',c.convalidated,'referenced_table',CASE WHEN c.confrelid=0 THEN NULL ELSE c.confrelid::regclass::text END) ORDER BY c.conrelid::regclass::text,c.conname) FROM pg_constraint c WHERE c.conrelid IN ('public.listings'::regclass,'public.donation_claims'::regclass,'public.claim_requests'::regclass,'public.claim_leases'::regclass,'public.pickup_tasks'::regclass) OR c.confrelid='public.listings'::regclass),
 'listing_triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'internal',t.tgisinternal,'enabled',t.tgenabled,'type',t.tgtype,'arguments',t.tgnargs,'columns',t.tgattr::text,'qualifier',pg_get_expr(t.tgqual,t.tgrelid),'definition',pg_get_triggerdef(t.oid),'function',t.tgfoid::regprocedure::text,'function_hash',md5(replace(p.prosrc,chr(13),'')),'function_definition',pg_get_functiondef(p.oid),'owner',p.proowner::regrole::text,'definer',p.prosecdef,'acl',p.proacl::text,'config',p.proconfig) ORDER BY t.tgname) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid='public.listings'::regclass),
 'migration_ledger',to_regclass('supabase_migrations.schema_migrations')::text,
 'history_related_tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'columns',(SELECT jsonb_agg(a.attname ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p') AND n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema' AND c.relname ~* '(migration|deployment|backup|restore)')
) AS catalog;
ROLLBACK;

BEGIN READ ONLY;
SELECT jsonb_build_object(
 'inspected_at',clock_timestamp(),'transaction_read_only',current_setting('transaction_read_only'),
 'static_dependencies',(SELECT coalesce(jsonb_agg(jsonb_build_object('referenced',d.refobjid::regprocedure::text,'dependent_type',d.classid::regclass::text,'dependent',pg_describe_object(d.classid,d.objid,d.objsubid),'dependency_type',d.deptype)),'[]'::jsonb) FROM pg_depend d WHERE d.refclassid='pg_proc'::regclass AND d.refobjid IN ('public.claim_listing(uuid,uuid)'::regprocedure,'public.geolock_lock_listing_donations(uuid,text[])'::regprocedure,'public.geolock_transition_listing_donations(uuid,text,text)'::regprocedure,'public.geolock_transition_listing_donations(uuid,text,text,uuid,uuid,text)'::regprocedure)),
 'referencing_views',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'view',viewname,'definition',definition)),'[]'::jsonb) FROM pg_views WHERE definition ~* '(geolock_lock_listing_donations|geolock_transition_listing_donations|claim_listing)'),
 'dynamic_reference_candidates',(SELECT coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'hash',md5(replace(prosrc,chr(13),'')))),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','routing_private','resolution_private','fleet_private') AND p.prosrc ~* '(execute|regprocedure)' AND p.prosrc ~* '(listing_donations|claim_listing)'),
 'relevant_columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid='public.listings'::regclass AND a.attnum>0 AND NOT a.attisdropped),
 'unvalidated_constraints',(SELECT coalesce(jsonb_agg(c.conname),'[]'::jsonb) FROM pg_constraint c WHERE (c.conrelid='public.listings'::regclass OR c.confrelid='public.listings'::regclass) AND NOT c.convalidated)
) AS dependencies; ROLLBACK;

BEGIN READ ONLY;
SELECT jsonb_build_object(
 'transaction_read_only',current_setting('transaction_read_only'),'inspected_at',clock_timestamp(),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'bypassrls',rolbypassrls,'login',rolcanlogin) ORDER BY rolname) FROM pg_roles WHERE rolname IN ('postgres','anon','authenticated','service_role','geolock_planner','geolock_validator','geolock_graph_worker','geolock_route_resolver')),
 'effective_execute',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'role',r.rolname,'execute',has_function_privilege(r.oid,p.oid,'EXECUTE')) ORDER BY p.oid::regprocedure::text,r.rolname) FROM pg_proc p CROSS JOIN pg_roles r WHERE r.rolname IN ('anon','authenticated','service_role','geolock_planner','geolock_validator','geolock_graph_worker','geolock_route_resolver') AND p.oid IN ('public.claim_listing(uuid,uuid)'::regprocedure,'public.cancel_claim(uuid,uuid)'::regprocedure,'public.submit_claim_reconciliation(uuid,boolean,uuid)'::regprocedure,'public.geolock_lock_listing_donations(uuid,text[])'::regprocedure)),
 'memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('role',r.rolname,'member',m.rolname,'admin',a.admin_option,'inherit',a.inherit_option,'set',a.set_option)),'[]'::jsonb) FROM pg_auth_members a JOIN pg_roles r ON r.oid=a.roleid JOIN pg_roles m ON m.oid=a.member WHERE m.rolname IN ('anon','authenticated','service_role','geolock_planner','geolock_validator','geolock_graph_worker','geolock_route_resolver'))
) AS privileges;ROLLBACK;
